INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_CIV','The Children of the Kingdom');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_CIV5_HEADING_1','A life shaped by prayer');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_CIV5_TEXT_1','The Children of the Kingdom are a fictional community inspired by the Lord''s Prayer in Matthew 6:9–13. Their common life begins in Sanctuary and grows through devotion, humility, forgiveness and trust in God''s will. Their strength comes from steady prayer rather than conquest.[NEWLINE][NEWLINE]The seven petitions move from addressing the Father, through praise, seeking, daily provision, repentance and protection, to a closing doxology. The familiar closing words belong to the traditional doxology; Christian traditions differ in their liturgical use and textual placement. The seven-stage cycle is a gameplay structure, not a claim that every tradition divides the prayer in this way.[NEWLINE][NEWLINE]Grace represents enduring spiritual growth within this fictional civilization. It is not an assertion that divine favor can be measured or earned as a game currency.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_CIV_PEDIA','The Children of the Kingdom are a fictional community inspired by the Lord''s Prayer in Matthew 6:9–13. Their common life begins in Sanctuary and grows through devotion, humility, forgiveness and trust in God''s will. Their strength comes from steady prayer rather than conquest.[NEWLINE][NEWLINE]The seven petitions move from addressing the Father, through praise, seeking, daily provision, repentance and protection, to a closing doxology. The familiar closing words belong to the traditional doxology; Christian traditions differ in their liturgical use and textual placement. The seven-stage cycle is a gameplay structure, not a claim that every tradition divides the prayer in this way.[NEWLINE][NEWLINE]Grace represents enduring spiritual growth within this fictional civilization. It is not an assertion that divine favor can be measured or earned as a game currency.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_CLOSE','Close');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_CONFIRM','{1_Name} prayed. The next petition is {2_Next}; available in {3_Turns} turns.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_CURRENT','Current Petition: {1_Name}');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_CYCLE_HELP','Petitions follow this fixed order: Address, Opening Glory, Seek, Ask, Repent, Protection, Closing Glory. Cycle shows the NEXT petition. Era level is 1 in Ancient, 2 in Classical, and so on. Blessing durations and the prayer cooldown scale with the active game speed.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_DAWN','Faithful servant, the people of Sanctuary gather in the morning light. Teach them to seek the kingdom, share their daily bread and forgive as they hope to be forgiven.[NEWLINE][NEWLINE]Let prayer sustain their work and steadfast defenders preserve their peace. Through patient devotion, may this humble beginning become a civilization of enduring faith and culture.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_DEFENDER','Stand Firm — defending at home');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_DEFENDER_HELP','+15% strength when defending. Active only in friendly territory. No attack bonus.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_DISABLED','Prayer state could not be read safely. Effects are disabled; see Lua.log. The original saved data has been preserved.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_DUMMY','Kingdom blessing');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_DUMMY_HELP','Automatically maintained by Prayer; cannot be built or purchased.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_EFFECT_1','Capital: +2 Faith and +1 Food per turn for {1_Turns} turns.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_EFFECT_2','Immediately receive {2_Faith} Faith (10 per Era level).');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_EFFECT_3','Every owned city: +15% Culture for {1_Turns} turns.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_EFFECT_4','Capital: immediately gain {3_Yield} Food and {3_Yield} Production (8 each per Era level). Production beyond the current item, or without a finite queue, is safely held in a saved reserve.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_EFFECT_5','+2 Global Happiness for {1_Turns} turns.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_EFFECT_6','All owned cities: +20% City Strength for {1_Turns} turns. Military units: +15% strength only when defending in friendly territory for the same duration.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_EFFECT_7','Gain {4_GAP} Golden Age Points (20 per Era level), one permanent Grace (maximum 7), and 10 Faith per completed House of Prayer. At 7 Grace, gain {5_Excess} extra Golden Age Points (25 per Era level) instead. The next petition is Address.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_FAITHFUL_HEADING_1','Prayer and service');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_FAITHFUL_LIVED','The age of faithful perseverance');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_FAITHFUL_NAME','The Faithful');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_FAITHFUL_SUBTITLE','A servant among the people');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_FAITHFUL_TEXT_1','The Faithful represents a community''s shared commitment to prayer and service. This fictional leader seeks neither personal glory nor a kingdom built by violence. Their task is to preserve a people who can ask for daily bread, forgive their neighbors and persevere through hardship.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_FAITHFUL_TITLES_1','The Faithful');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_GRACE_CAP','A full prayer is complete. Grace remains 7/7; receive {1_GAP} additional Golden Age Points.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_GRACE_GAIN','A full prayer is complete. Grace: {1_Grace}/7. Each Grace gives the capital +1 Faith and +1 Culture per turn.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_HOUSE','House of Prayer');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_HOUSE_HELP','Replaces Temple, retaining its active costs, prerequisites, maintenance and all ordinary Temple effects. A completed House in a human Kingdom city additionally provides +1 Faith and +1 Culture. Each currently owned, completed House grants 10 Faith whenever Closing Glory is prayed.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_HOUSE_PEDIA','A House of Prayer is a place for devotion, reconciliation and the sharing of daily bread. Within its stone walls, neighbors learn that humility and forgiveness are practices to renew throughout a lifetime. The building preserves the Temple''s ordinary role while supporting the prayer cycle.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_HOUSE_REWARD','Completed Houses of Prayer: {1_Count}. Closing Glory grants {2_Faith} additional Faith.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_HOUSE_STRATEGY','Build Houses where you can support the normal Temple maintenance. Their additional Faith and Culture support cultural and diplomatic development; completing prayer cycles rewards every House currently owned.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_LEADER','The Faithful');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_LEADER_PEDIA','The Faithful represents a community''s shared commitment to prayer and service. This fictional leader seeks neither personal glory nor a kingdom built by violence. Their task is to preserve a people who can ask for daily bread, forgive their neighbors and persevere through hardship.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_NONE','No temporary blessings are active.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_OPEN','[ICON_PEACE] Prayer');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_PERMANENT','Permanent capital blessing: +{1_Grace} Faith and +{1_Grace} Culture per turn.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_PRAY','PRAY');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_PROGRESS','Grace: {1_Grace}/7     Cycle: {2_Stage}/7');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_PROTECTION_POLICY','Deliverance');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_PROTECTION_POLICY_HELP','+20% City Strength in all owned cities during Protection.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_QUOTE_1','Our Father in heaven.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_QUOTE_2','Hallowed be Your name.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_QUOTE_3','Your kingdom come, Your will be done.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_QUOTE_4','Give us this day our daily bread.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_QUOTE_5','Forgive us our debts, as we forgive our debtors.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_QUOTE_6','Lead us not into temptation, but deliver us from evil.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_QUOTE_7','For Yours is the kingdom, the power, and the glory forever.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_READY_HELP','Pray the current petition once. The next petition becomes available after {1_Turns} turns.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_REPENT_POLICY','Forgiveness');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_REPENT_POLICY_HELP','+2 Global Happiness during Repent; counted once in the empire.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_RESERVE','Daily bread Production reserve: {1_Amount}. Applied safely to a finite capital queue; it moves with the capital.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_SHIELD','Protection — defending at home');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_SHIELD_HELP','+15% strength when defending in friendly territory during Protection. Separate from Stand Firm. No attack bonus.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_SHORT','Children of the Kingdom');
