INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_STAGE_1','ADDRESS');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_STAGE_2','OPENING GLORY');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_STAGE_3','SEEK');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_STAGE_4','ASK');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_STAGE_5','REPENT');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_STAGE_6','PROTECTION');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_STAGE_7','CLOSING GLORY');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_STAND','Stand Firm');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_STAND_HELP','+15% defensive strength in friendly territory and +5 HP per eligible healing turn there. Retained on upgrade. Human Kingdom players only.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_STRATEGY','Pray consistently, develop Houses of Prayer, and defend your cities while Grace slowly strengthens the capital. Culture and Diplomatic victories suit this patient civilization. Early blessings are modest; protecting experienced Keepers and completing seven-stage cycles matters more than conquest.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_TITLE','THE CHILDREN OF THE KINGDOM — PRAYER');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_TRAIT','Thy Kingdom Come');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_TRAIT_HELP','Human players only. Open Prayer to activate seven petitions in order, once every 5 turns on Standard speed (scaled with game speed). Complete a cycle for one permanent Grace, maximum 7: each gives the capital +1 Faith and +1 Culture per turn. Closing Glory also grants 20 Golden Age Points per Era level and 10 Faith per completed House of Prayer. At maximum Grace, each further cycle gives 25 additional Golden Age Points per Era level. See Prayer for every blessing.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_UNAVAILABLE','Prayer requires an active human Kingdom turn and an owned capital. Multiplayer and hotseat are unsupported.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_UNIT','Keeper of the Faith');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_UNIT_HELP','Replaces Pikeman and retains its normal characteristics and anti-mounted role. For human Kingdom players, Stand Firm grants +15% strength only when defending in friendly territory and +5 HP per eligible healing turn in friendly territory. Stand Firm persists through upgrades. Protection is a separate +15% defensive bonus; neither strengthens attacks.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_UNIT_PEDIA','Keepers understand steadfastness as service. They guard homes, pilgrims and the quiet labor of their neighbors. Their pikes retain the ordinary battlefield role of the Pikeman; their distinction is perseverance rather than a desire for conquest. The standard Pikeman model is deliberately retained.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_UNIT_STRATEGY','Hold friendly ground, protect cities and preserve experienced defenders through upgrades. Normal movement, healing eligibility and anti-mounted rules apply. Stand Firm does not enable healing after moving or during every turn.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_WAIT','Next Prayer: {1_Turns} turns');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CK_WAIT_HELP','This petition is not yet available. Wait {1_Turns} turns; changing screens or reloading does not reset the cooldown.');
